import ast
import os
import socket
from pathlib import Path

import requests

from tests.test_config import test_config


def _candidate_env_urls():
    seen = set()
    for value in (os.getenv('TEST_BASE_URL'), os.getenv('REACT_APP_BACKEND_URL'), test_config.TEST_BASE_URL):
        value = (value or '').rstrip('/')
        if value and value not in seen:
            seen.add(value)
            yield value


def _listen_ports():
    ports = set()
    for filename in ('/proc/net/tcp', '/proc/net/tcp6'):
        path = Path(filename)
        if not path.is_file():
            continue
        for line in path.read_text(encoding='utf-8', errors='replace').splitlines()[1:]:
            cols = line.split()
            if len(cols) < 4 or cols[3] != '0A':
                continue
            try:
                port = int(cols[1].split(':')[1], 16)
            except (IndexError, ValueError):
                continue
            if 1 <= port <= 65535:
                ports.add(port)
    return sorted(ports)


def _is_backend(url):
    try:
        response = requests.get(f'{url}/api/centro-control/ping', timeout=2)
        if response.status_code != 200:
            return False
        payload = response.json()
        return isinstance(payload, dict) and payload.get('status') == 'ok'
    except (requests.RequestException, ValueError):
        return False


def _base_url():
    for url in _candidate_env_urls():
        if _is_backend(url):
            return url
    for port in _listen_ports():
        url = f'http://127.0.0.1:{port}'
        if _is_backend(url):
            return url
    raise AssertionError('RUNTIME_BACKEND_NOT_DISCOVERED: no local listening origin answered /api/centro-control/ping with status=ok')


def _credentials():
    email = test_config.TEST_ADMIN_EMAIL
    password = test_config.TEST_ADMIN_PASSWORD
    assert email and password, 'RUNTIME_E2E_CONFIG_MISSING: TEST_ADMIN_EMAIL/TEST_ADMIN_PASSWORD'
    return {'email': email, 'password': password}


def _login_session():
    session = requests.Session()
    response = session.post(f'{_base_url()}/api/auth/login', json=_credentials(), timeout=20)
    assert response.status_code == 200, f'RUNTIME_LOGIN_FAILED: status={response.status_code}'
    payload = response.json()
    token = payload.get('token')
    assert token, 'RUNTIME_LOGIN_FAILED: token_missing'
    session.headers.update({'Authorization': f'Bearer {token}'})
    return session


def test_runtime_backend_is_discovered_and_centro_ping_is_public():
    url = _base_url()
    response = requests.get(f'{url}/api/centro-control/ping', timeout=20)
    assert response.status_code == 200
    assert response.json().get('status') == 'ok'


def test_runtime_rbac_rejects_unauthenticated_requests_for_both_modules():
    url = _base_url()
    centro = requests.get(f'{url}/api/centro-control/estado', timeout=20)
    sync = requests.get(f'{url}/api/admin/sync-monitor', timeout=20)
    assert centro.status_code in (401, 403), f'CENTRO_UNAUTH_EXPECTED_401_403: status={centro.status_code}'
    assert sync.status_code in (401, 403), f'SYNC_UNAUTH_EXPECTED_401_403: status={sync.status_code}'


def test_runtime_authenticated_session_can_load_centro_control():
    session = _login_session()
    response = session.get(f'{_base_url()}/api/centro-control/estado', timeout=30)
    assert response.status_code == 200, f'CENTRO_RBAC_OR_RUNTIME_FAILED: status={response.status_code}'
    assert isinstance(response.json(), dict)


def test_runtime_authenticated_session_can_load_sync_monitor():
    session = _login_session()
    response = session.get(f'{_base_url()}/api/admin/sync-monitor', timeout=30)
    assert response.status_code == 200, f'SYNC_RBAC_OR_RUNTIME_FAILED: status={response.status_code}'
    payload = response.json()
    assert isinstance(payload, dict)
    assert 'procesos' in payload
    assert 'kpis' in payload


def test_runtime_centro_control_core_endpoints_load_with_same_session():
    session = _login_session()
    paths = [
        '/api/centro-control/salud/resumen',
        '/api/centro-control/alertas',
        '/api/centro-control/fuentes',
        '/api/centro-control/jobs',
        '/api/centro-control/bitacora',
        '/api/centro-control/metricas',
        '/api/centro-control/historial',
        '/api/centro-control/matriz-resolucion',
        '/api/centro-control/blindaje/modulos',
    ]
    for path in paths:
        response = session.get(f'{_base_url()}{path}', timeout=30)
        assert response.status_code == 200, f'CENTRO_ENDPOINT_FAILED: path={path} status={response.status_code}'


def test_runtime_external_notification_configuration_is_truthful_without_assuming_credentials():
    session = _login_session()
    responses = {
        'email': session.get(f'{_base_url()}/api/centro-control/email/config', timeout=20),
        'whatsapp': session.get(f'{_base_url()}/api/centro-control/whatsapp/config', timeout=20),
        'all': session.get(f'{_base_url()}/api/centro-control/notificaciones/config', timeout=20),
    }
    for name, response in responses.items():
        assert response.status_code == 200, f'NOTIFICATION_CONFIG_FAILED: service={name} status={response.status_code}'
    email_cfg = responses['email'].json().get('config')
    whatsapp_cfg = responses['whatsapp'].json().get('config')
    servicios = responses['all'].json().get('servicios')
    assert isinstance(email_cfg, dict)
    assert isinstance(whatsapp_cfg, dict)
    assert isinstance(servicios, dict)
    for field in ('configured', 'enabled'):
        assert field in email_cfg and isinstance(email_cfg[field], bool)
    for field in ('configured', 'enabled', 'twilio_configured'):
        assert field in whatsapp_cfg and isinstance(whatsapp_cfg[field], bool)
    assert {'email', 'whatsapp', 'websocket'}.issubset(servicios.keys())


def test_runtime_e2e_contains_no_forbidden_external_post_calls():
    tree = ast.parse(Path(__file__).read_text(encoding='utf-8'))
    post_targets = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute) or node.func.attr != 'post' or not node.args:
            continue
        arg = node.args[0]
        if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
            post_targets.append(arg.value)
        elif isinstance(arg, ast.JoinedStr):
            literal = ''.join(part.value for part in arg.values if isinstance(part, ast.Constant) and isinstance(part.value, str))
            post_targets.append(literal)
    forbidden = ('/email/' + 'test', '/whatsapp/' + 'test', '/alerta-' + 'critica')
    assert not any(any(fragment in target for fragment in forbidden) for target in post_targets), f'FORBIDDEN_EXTERNAL_POST_CALL: {post_targets}'
